function [out_x, out_y, out_z] = cordic_s1(x_in, y_in, z_in, num_iterations, mode)
    % Unified CORDIC algorithm for both Rotation and Vectoring modes
    % Inputs:
    %   x_in, y_in : Input vector coordinates (Real and Imaginary)
    %   z_in       : Target angle (Rotation) or Initial angle offset (Vectoring)
    %   num_iterations : Number of iterations for the CORDIC algorithm (accuracy vs. complexity)
    %   mode       : 0: rotation mode or 1: vector mode
    % Outputs:
    %   out_x, out_y : Output vector coordinates (Real and Imaginary)


    % Precompute arctan values for the iterations
    % atan_table = atan(2.^-(0:num_iterations-1));
    fm = get_fimath();

    atan_table = fi([0.7854  0.4636  0.2450  0.1244  0.0624  0.0312  0.0156  0.0078  0.0039  0.0020  0.0018  0.0005 ], 0, 12, 12, fm);

    x_reg = fi(x_in, 1, 12, 3, fm);
    y_reg = fi(y_in, 1, 12, 3, fm);
    z_reg = fi(z_in, 1, 12, 7, fm);
    
    %% --- ROTATION MODE (Steering the Antenna Phase) ---
    if mode == fi(0, 0, 1, 0, fm)
        % 1. Quadrant Mapping: Fold the angle into [-pi/2, pi/2]
        z_reg = fi(fi_signed(mod(z_reg + fi(pi, 0, 10, 8, fm), fi(2*pi, 0, 10, 7, fm))) - fi(pi, 0, 10, 8, fm), 1, 12, 7, fm); % Wrap to [-pi, pi]
        if z_reg > fi(pi/2, 0, 10, 9, fm)
            x_reg(:) = fi_uminus(x_in); y_reg(:) = fi_uminus(y_in); z_reg = fi(z_reg - fi(pi, 0, 10, 8, fm), 1, 12, 7, fm);
        elseif z_reg < fi(-pi/2, 1, 10, 8, fm)
            x_reg(:) = fi_uminus(x_in); y_reg(:) = fi_uminus(y_in); z_reg = fi(z_reg + fi(pi, 0, 10, 8, fm), 1, 12, 7, fm);
        end
        
        % 2. Iterative Rotation
        for i = fi(0, 0, 1, 0, fm):fi_signed(num_iterations)-fi(1, 0, 1, 0, fm)
            if z_reg > fi(0, 0, 1, 0, fm)
                % Rotate counter-clockwise
                x_temp = fi(x_reg - bitsra(y_reg, fi_toint(i)), 1, 12, 3, fm); % x_reg - (y_reg * 2^(-i))
                y_temp = fi(y_reg + bitsra(x_reg, fi_toint(i)), 1, 12, 3, fm); % y_reg + (
                z_temp = fi(z_reg - atan_table(i+fi(1, 0, 1, 0, fm)), 1, 12, 9, fm);
            else
                % Rotate clockwise
                x_temp = fi(x_reg + bitsra(y_reg, fi_toint(i)), 1, 12, 3, fm); % x_reg + (y_reg * 2^(-i))
                y_temp = fi(y_reg - bitsra(x_reg, fi_toint(i)), 1, 12, 3, fm); % y_reg - (x_reg * 2^(-i))
                z_temp = fi(z_reg + atan_table(i+fi(1, 0, 1, 0, fm)), 1, 12, 9, fm);
            end
            x_reg(:) = x_temp; y_reg(:) = y_temp; z_reg = fi(z_temp, 1, 12, 7, fm);
        end
        
    %% --- VECTORING MODE (Extracting the Phase) ---
    elseif mode == fi(1, 0, 1, 0, fm)
        % 1. Quadrant Mapping: Force the vector into the right half-plane (X > 0)
        if x_reg < fi(0, 0, 1, 0, fm)
            if y_reg >= fi(0, 0, 1, 0, fm)
                z_reg = fi(z_reg + fi(pi, 0, 10, 8, fm), 1, 12, 7, fm); % Vector was in Q2
            else
                z_reg = fi(z_reg - fi(pi, 0, 10, 8, fm), 1, 12, 7, fm); % Vector was in Q3
            end
            x_reg(:) = fi_uminus(x_reg); 
            y_reg(:) = fi_uminus(y_reg);
        end
        
        % 2. Iterative Vectoring (Drive Y to 0)
        for i = fi(0, 0, 1, 0, fm):fi_signed(num_iterations)-fi(1, 0, 1, 0, fm)
            if y_reg > fi(0, 0, 1, 0, fm)
                % Rotate clockwise to reduce Y
                x_temp = fi(x_reg + bitsra(y_reg, fi_toint(i)), 1, 12, 3, fm); % x_reg + (y_reg * 2^(-i))
                y_temp = fi(y_reg - bitsra(x_reg, fi_toint(i)), 1, 12, 3, fm); % y_reg - (x_reg * 2^(-i))
                z_temp = fi(z_reg + atan_table(i+fi(1, 0, 1, 0, fm)), 1, 12, 9, fm);
            else
                % Rotate counter-clockwise to increase Y
                x_temp = fi(x_reg - bitsra(y_reg, fi_toint(i)), 1, 12, 3, fm); % x_reg - (y_reg * 2^(-i))
                y_temp = fi(y_reg + bitsra(x_reg, fi_toint(i)), 1, 12, 3, fm); % y_reg + (x_reg * 2^(-i))
                z_temp = fi(z_reg - atan_table(i+fi(1, 0, 1, 0, fm)), 1, 12, 9, fm);
            end
            x_reg(:) = x_temp; y_reg(:) = y_temp; z_reg = fi(z_temp, 1, 12, 7, fm);
        end
    end
    
    % --- Apply CORDIC Gain (approx 1.6467 for 10 iters) ---
    % In a strict 3000 FF hardware design, you might skip this division 
    % if you only care about the phase (z_reg) or relative magnitude.
    % gain = prod(sqrt(1 + 2.^-(2*(0:num_iterations-1))));
    gain = fi(1.6467, 0, 10, 9, fm); % Precomputed gain for 10 iterations
    out_x = fi(fi_div(x_reg, gain), 1, 10, 2, fm);
    out_y = fi(fi_div(y_reg, gain), 1, 10, 2, fm);
    out_z = fi(z_reg, 1, 10, 7, fm);
end

% =========================================================================
% Function: monopulse_tracking
% Multiplier-less monopulse tracking using CORDIC for rotation and vectoring.
% The received-signal matrix X (N x num_samples) must be provided by the caller.
% Usage:
%   theta_track = monopulse_tracking(X, N, d_lambda, cordic_iters, theta_init, K_track)
function theta_track = monopulse_tracking(X, N_1, d_lambda_1, cordic_iters_1, theta_init_1, K_track_1)

% Validate input X
fm = get_fimath();
K_track = fi(K_track_1, 0, 10, 8, fm);
N = fi(N_1, 0, 3, 0, fm);
cordic_iters = fi(cordic_iters_1, 0, 4, 0, fm);
d_lambda = fi(d_lambda_1, 0, 10, 10, fm);
theta_init = fi(theta_init_1, 1, 7, 0, fm);

if nargin < 1 || isempty(X)
    %F2F: No information found for converting the following block of code
    %F2F: Start block
    error('Input X (N x num_samples) must be provided by the testbench');
    %F2F: End block
end

% Dimensions
[fmo_1, fmo_2] = size(X);
N_fromX = fi(fmo_1, 0, 3, 0, fm);
num_samples = fi(fmo_2, 0, 6, 0, fm);
if nargin < 2 || isempty(N), 
%F2F: No information found for converting the following block of code
%F2F: Start block
N = fi(N_fromX, 0, 3, 0, fm);
%F2F: End block
 end
if N ~= N_fromX
    %F2F: No information found for converting the following block of code
    %F2F: Start block
    error('Provided N (%d) does not match rows of X (%d)', N, N_fromX);
    %F2F: End block
end

% Defaults
if nargin < 3 || isempty(d_lambda), 
%F2F: No information found for converting the following block of code
%F2F: Start block
d_lambda = fi(0.5, 0, 10, 10, fm);
%F2F: End block
 end
if nargin < 4 || isempty(cordic_iters), 
%F2F: No information found for converting the following block of code
%F2F: Start block
cordic_iters = fi(10, 0, 4, 0, fm);
%F2F: End block
 end
if nargin < 5 || isempty(theta_init), 
%F2F: No information found for converting the following block of code
%F2F: Start block
theta_init = fi(15, 1, 7, 0, fm);
%F2F: End block
 end
if nargin < 6 || isempty(K_track), 
%F2F: No information found for converting the following block of code
%F2F: Start block
K_track = fi(2^(-4) * (180/pi), 0, 10, 8, fm);
%F2F: End block
 end

theta_track = fi(zeros(1, fi_toint(num_samples)), 1, 8, 0, fm);
theta_track(1) = fi(theta_init, 1, 8, 0, fm);

for n = fi(1, 0, 1, 0, fm):num_samples-fi(1, 0, 1, 0, fm)
    % Use the pre-generated received sample for this time index
    X_sample = fi(X(:, n), 1, 10, 6, fm);

    % Beam steering (CORDIC rotation mode)
    X_steered = fi(zeros(fi_toint(N), 1) + 1j*zeros(fi_toint(N), 1), 1, 10, 6, fm);
    for k = fi(1, 0, 1, 0, fm):N
        phi_target = fi(fi(fi(2 * pi, 0, 10, 7, fm) * d_lambda * (k-fi(1, 0, 1, 0, fm)), 'SumMode', 'KeepLSB') * fi(sind_lut_s2(theta_track(n)), 'SumMode', 'KeepLSB'), 1, 10, 5, fm);
        q_in = fi(real(X_sample(k)), 1, 10, 6, fm);
        i_in = fi(imag(X_sample(k)), 1, 10, 6, fm);
        [fmo_3, fmo_4, ~] = cordic_s1(fi(q_in, 1, 10, 3, fm), fi(i_in, 1, 10, 3, fm), phi_target, cordic_iters, fi(0, 0, 1, 0, fm));
        Q_rot = fi(fmo_3, 1, 10, 6, fm);
        I_rot = fi(fmo_4, 1, 10, 6, fm);
        X_steered(k) = Q_rot + fi(1j, 0, 1, 0, fm) * I_rot;
    end

    % Sub-array grouping (Left and Right halves)
    if N < fi(4, 0, 3, 0, fm)
        %F2F: No information found for converting the following block of code
        %F2F: Start block
        error('monopulse_tracking requires N >= 4 for 2x2 subarray grouping');
        %F2F: End block
    end
    L = fi(X_steered(1) + X_steered(2), 1, 10, 6, fm);
    R = fi(X_steered(3) + X_steered(4), 1, 10, 6, fm);

    % Phase extraction (CORDIC vectoring mode)
    [~, ~, fmo_5] = cordic_s2(fi(real(L), 1, 10, 3, fm), imag(L), fi(fi(0, 0, 1, 0, fm), 1, 10, 5, fm), cordic_iters, fi(1, 0, 1, 0, fm));
    phi_L = fi(fmo_5, 0, 10, 8, fm);
    [~, ~, fmo_6] = cordic_s2(fi(real(R), 1, 10, 3, fm), imag(R), fi(fi(0, 0, 1, 0, fm), 1, 10, 5, fm), cordic_iters, fi(1, 0, 1, 0, fm));
    phi_R = fi(fmo_6, 1, 10, 7, fm);
    % phase_diff = wrapToPi(phi_L - phi_R);
    % Fixed-point friendly phase wrapping to [-pi, pi]
    phase_diff = fi(phi_L - phi_R, 1, 10, 7, fm);
    phase_diff(:) = phase_diff - fi(2*pi, 0, 10, 7, fm)*floor((phase_diff + fi(pi, 0, 10, 8, fm))*fi(1/(2*pi), 0, 10, 1000, fm));

    % Magnitude approximation and thresholding
    mag_L = fi(abs(real(L)) + abs(imag(L)), 0, 10, 6, fm);
    mag_R = fi(abs(real(R)) + abs(imag(R)), 0, 10, 6, fm);

    if (mag_L + mag_R) > fi(0.5, 0, 10, 10, fm)
        theta_track_tmp = fi(theta_track(n) + K_track * phase_diff, 1, 10, 2, fm);
        theta_track(n+fi(1, 0, 1, 0, fm)) = fi(round(theta_track_tmp), 1, 8, 0, fm);
    else
        %F2F: No information found for converting the following block of code
        %F2F: Start block
        theta_track(n+fi(1, 0, 1, 0, fm)) = fi(theta_track(n), 1, 8, 0, fm);
        %F2F: End block
    end
end

end

