function [out_x, out_y, out_z] = cordic_s2(x_in, y_in, z_in, num_iterations, mode)
    % Unified CORDIC algorithm for both Rotation and Vectoring modes
    % Inputs:
    %   x_in, y_in : Input vector coordinates (Real and Imaginary)
    %   z_in       : Target angle (Rotation) or Initial angle offset (Vectoring)
    %   num_iterations : Number of iterations for the CORDIC algorithm (accuracy vs. complexity)
    %   mode       : 0: rotation mode or 1: vector mode
    % Outputs:
    %   out_x, out_y : Output vector coordinates (Real and Imaginary)


    % Precompute arctan values for the iterations
    % atan_table = atan(2.^-(0:num_iterations-1));
    fm = get_fimath();

    atan_table = fi([0.7854  0.4636  0.2450  0.1244  0.0624  0.0312  0.0156  0.0078  0.0039  0.0020  0.0018  0.0005 ], 0, 12, 12, fm);

    x_reg = fi(x_in, 1, 12, 3, fm);
    y_reg = fi(y_in, 1, 12, 3, fm);
    z_reg = fi(z_in, 1, 12, 7, fm);
    
    %% --- ROTATION MODE (Steering the Antenna Phase) ---
    if mode == fi(0, 0, 1, 0, fm)
        % 1. Quadrant Mapping: Fold the angle into [-pi/2, pi/2]
        z_reg(:) = fi_signed(mod(z_reg + fi(pi, 0, 10, 8, fm), fi(2*pi, 0, 10, 7, fm))) - fi(pi, 0, 10, 8, fm); % Wrap to [-pi, pi]
        if z_reg > fi(pi/2, 0, 10, 9, fm)
            x_reg(:) = fi_uminus(x_in); y_reg(:) = fi_uminus(y_in); z_reg(:) = z_reg - fi(pi, 0, 10, 8, fm);
        elseif z_reg < fi(-pi/2, 1, 10, 8, fm)
            x_reg(:) = fi_uminus(x_in); y_reg(:) = fi_uminus(y_in); z_reg(:) = z_reg + fi(pi, 0, 10, 8, fm);
        end
        
        % 2. Iterative Rotation
        for i = fi(0, 0, 1, 0, fm):fi_signed(num_iterations)-fi(1, 0, 1, 0, fm)
            if z_reg > fi(0, 0, 1, 0, fm)
                % Rotate counter-clockwise
                x_temp = fi(x_reg - bitsra(y_reg, fi_toint(i)), 1, 12, 3, fm); % x_reg - (y_reg * 2^(-i))
                y_temp = fi(y_reg + bitsra(x_reg, fi_toint(i)), 1, 12, 3, fm); % y_reg + (
                z_temp = fi(z_reg - atan_table(i+fi(1, 0, 1, 0, fm)), 1, 12, 9, fm);
            else
                % Rotate clockwise
                x_temp = fi(x_reg + bitsra(y_reg, fi_toint(i)), 1, 12, 3, fm); % x_reg + (y_reg * 2^(-i))
                y_temp = fi(y_reg - bitsra(x_reg, fi_toint(i)), 1, 12, 3, fm); % y_reg - (x_reg * 2^(-i))
                z_temp = fi(z_reg + atan_table(i+fi(1, 0, 1, 0, fm)), 1, 12, 9, fm);
            end
            x_reg(:) = x_temp; y_reg(:) = y_temp; z_reg(:) = z_temp;
        end
        
    %% --- VECTORING MODE (Extracting the Phase) ---
    elseif mode == fi(1, 0, 1, 0, fm)
        % 1. Quadrant Mapping: Force the vector into the right half-plane (X > 0)
        if x_reg < fi(0, 0, 1, 0, fm)
            if y_reg >= fi(0, 0, 1, 0, fm)
                z_reg(:) = z_reg + fi(pi, 0, 10, 8, fm); % Vector was in Q2
            else
                z_reg(:) = z_reg - fi(pi, 0, 10, 8, fm); % Vector was in Q3
            end
            x_reg(:) = fi_uminus(x_reg); 
            y_reg(:) = fi_uminus(y_reg);
        end
        
        % 2. Iterative Vectoring (Drive Y to 0)
        for i = fi(0, 0, 1, 0, fm):fi_signed(num_iterations)-fi(1, 0, 1, 0, fm)
            if y_reg > fi(0, 0, 1, 0, fm)
                % Rotate clockwise to reduce Y
                x_temp = fi(x_reg + bitsra(y_reg, fi_toint(i)), 1, 12, 3, fm); % x_reg + (y_reg * 2^(-i))
                y_temp = fi(y_reg - bitsra(x_reg, fi_toint(i)), 1, 12, 3, fm); % y_reg - (x_reg * 2^(-i))
                z_temp = fi(z_reg + atan_table(i+fi(1, 0, 1, 0, fm)), 1, 12, 9, fm);
            else
                % Rotate counter-clockwise to increase Y
                x_temp = fi(x_reg - bitsra(y_reg, fi_toint(i)), 1, 12, 3, fm); % x_reg - (y_reg * 2^(-i))
                y_temp = fi(y_reg + bitsra(x_reg, fi_toint(i)), 1, 12, 3, fm); % y_reg + (x_reg * 2^(-i))
                z_temp = fi(z_reg - atan_table(i+fi(1, 0, 1, 0, fm)), 1, 12, 9, fm);
            end
            x_reg(:) = x_temp; y_reg(:) = y_temp; z_reg(:) = z_temp;
        end
    end
    
    % --- Apply CORDIC Gain (approx 1.6467 for 10 iters) ---
    % In a strict 3000 FF hardware design, you might skip this division 
    % if you only care about the phase (z_reg) or relative magnitude.
    % gain = prod(sqrt(1 + 2.^-(2*(0:num_iterations-1))));
    gain = fi(1.6467, 0, 10, 9, fm); % Precomputed gain for 10 iterations
    out_x = fi(fi_div(x_reg, gain), 1, 10, 2, fm);
    out_y = fi(fi_div(y_reg, gain), 1, 10, 2, fm);
    out_z = fi(z_reg, 1, 10, 7, fm);
end



function ntype = divideType(a,b)
    coder.inline( 'always' );
    nt1 = numerictype( a );
    nt2 = numerictype( b );
    maxFL = max( [ min( nt1.WordLength, nt1.FractionLength ), min( nt2.WordLength, nt2.FractionLength ) ] );
    FL = max( maxFL, 24 );
    extraBits = (FL - maxFL);
    WL = nt1.WordLength + nt2.WordLength;
    WL = min( WL, 124 );
    if (WL + extraBits)<64
        ntype = numerictype( nt1.Signed || nt2.Signed, WL + extraBits, FL );
    else
        ntype = numerictype( nt1.Signed || nt2.Signed, WL, FL );
    end
end


function c = fi_div(a,b)
    coder.inline( 'always' );
    a1 = fi( a, 'RoundMode', 'fix' );
    b1 = fi( b, 'RoundMode', 'fix' );
    nType = divideType( a1, b1 );
    if isfi( a ) && isfi( b ) && isscalar( b )
        c1 = divide( nType, a1, b1 );
        c = fi( c1, numerictype( c1 ), fimath( a ) );
    else
        c = fi( a / b, nType );
    end
end


function y = fi_signed(a)
    coder.inline( 'always' );
    if isfi( a ) && ~(issigned( a ))
        nt = numerictype( a );
        new_nt = numerictype( 1, nt.WordLength + 1, nt.FractionLength );
        y = fi( a, new_nt, fimath( a ) );
    else
        y = a;
    end
end


function y = fi_toint(u)
    coder.inline( 'always' );
    if isfi( u )
        nt = numerictype( u );
        s = nt.SignednessBool;
        wl = nt.WordLength;
        y = int32( fi( u, s, wl, 0, hdlfimath ) );
    else
        y = int32( u );
    end
end


function y = fi_uminus(a)
    coder.inline( 'always' );
    if isfi( a )
        nt = numerictype( a );
        new_nt = numerictype( 1, nt.WordLength + 1, nt.FractionLength );
        y = -fi( a, new_nt, fimath( a ) );
    else
        y = -a;
    end
end

function fm = get_fimath()
	fm = fimath('RoundingMethod', 'Floor',...
	     'OverflowAction', 'Saturate',...
	     'ProductMode','FullPrecision',...
	     'SumMode','FullPrecision');
end
